INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 25, 'theory', 'Quiz: oVirt operations');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 0, 'What is the correct order of upgrading an oVirt installation?', '["Hosts, then the engine, then the data center version", "Cluster version, engine, hosts", "Backup, engine, hosts one by one, cluster and data center versions", "Engine and all hosts at once, backup afterward"]', 2, 'First the backup and the engine upgrade, then hosts one by one via maintenance, and only then the compatibility version: the cluster, then the data center.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 1, 'A machine did not start and the engine shows a command error. Where is it most sensible to start looking for the cause?', '["Take the correlation id from engine.log and find it in the chosen host''s vdsm.log, then in the libvirt and QEMU logs", "Reinstall the host right away", "Restart the engine and see whether the error goes away", "Disable SELinux on all hosts"]', 0, 'We follow the chain of layers: engine, VDSM, libvirt, QEMU. The correlation id ties a command''s lines across logs and exposes the first error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 2, 'What most often causes the NonOperational host state?', '["The host was put into maintenance", "The host lost its heartbeat", "The engine is being upgraded", "The host lacks a required logical network or cannot see a storage domain"]', 3, 'The link to the host works, but it does not meet the cluster''s requirements: a network or storage is missing. Lost contact gives NonResponsive, and servicing gives Maintenance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 3, 'What does N+1 capacity headroom mean for a cluster?', '["The cluster always has one host fewer than needed", "After the largest host fails, the remaining ones must still fit all the machines", "There must be memory for one extra virtual machine", "Each host needs a separate standby engine"]', 1, 'N+1 means that losing the largest host does not leave machines without room: the total capacity without it is at least the load.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 4, 'What is the status of oVirt as of 2026?', '["Closed, releases have stopped", "Developed by Red Hat, vendor support comes with a subscription", "A community project, latest release 4.5.7 in January 2026, Red Hat moved to OpenShift Virtualization", "Fully rewritten on Kubernetes"]', 2, 'The project lives on community effort: release 4.5.7 came out in January 2026, while Red Hat concentrated on OpenShift Virtualization.');
